import React, { useContext, useMemo } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { HTMLData } from './../../ricos-schema/next-schema/index.js';
import type { LegacyEditorPluginConfig } from './../../ricos-types/index.js';
import { containsUrl } from './../../_shared/link/contains-url.js';
import { normalizeUrl } from './../../_shared/link/normalize-url.js';

import { HTML_VIEWER_ROOT } from '../data-hooks.js';
import {
  INIT_HEIGHT,
  INIT_WIDTH,
  SRC_TYPE_HTML,
  SRC_TYPE_URL,
  SRC_TYPE_WIDGET,
} from '../defaults.js';
import { htmlFixer } from '../html-fixer.js';
import { IframeHtml } from '../iframe-html.js';
import { IframeUrl } from '../iframe-url.js';
import { IframeWidget } from '../iframe-widget.js';
import htmlStyles from '../statics/styles/HtmlComponent-scss.js';

const getPageURL = (siteDomain: string) => {
  if (!siteDomain) {
    return;
  }

  const regex = /http.+com/gm;
  const res = regex.exec(siteDomain);
  if (res) {
    return res[0];
  }
};

export type HtmlViewerProps = {
  settings: LegacyEditorPluginConfig;
  htmlData: HTMLData;
  iframeSandboxDomain?: string;
  isViewer?: boolean;
  onIframeHeightChange?: (height: number) => void;
};

export const HtmlViewer = React.forwardRef<HTMLDivElement, HtmlViewerProps>(
  ({ settings, htmlData, iframeSandboxDomain, onIframeHeightChange, isViewer = false }, ref) => {
    const { isMobile } = useContext(RicosContext);
    const [iframeHeight, setIframeHeight] = React.useState<number | undefined>();

    const setHeight = (height: number) => {
      if (height > 0 && height !== iframeHeight) {
        setIframeHeight(height);
      }
    };

    const getIframeHeight = useMemo(() => {
      const { containerData, autoHeight } = htmlData;

      if (autoHeight !== false && iframeHeight) {
        onIframeHeightChange?.(iframeHeight);

        return iframeHeight;
      }

      const customHeight = containerData?.height?.custom;

      const parsedCustomHeight = parseInt(customHeight || '');
      if (
        !customHeight ||
        (typeof customHeight === 'string' && customHeight.endsWith('%')) ||
        isNaN(parsedCustomHeight)
      ) {
        return iframeHeight || settings.height || INIT_HEIGHT;
      }

      return parsedCustomHeight;
    }, [htmlData, settings.height, iframeHeight]);

    const style = {
      width: isMobile
        ? 'auto'
        : htmlData.containerData?.width?.custom || settings.width || INIT_WIDTH + 'px',
      height: getIframeHeight + 'px',
      maxHeight: getIframeHeight + 'px',
    };

    const html = useMemo(() => {
      const pageURL = getPageURL(settings.siteDomain);
      return htmlFixer(htmlData.html, pageURL);
    }, [htmlData.html]);

    return (
      <div
        className={htmlStyles.htmlComponent}
        style={style}
        data-hook={HTML_VIEWER_ROOT}
        ref={ref}
      >
        {htmlData.widgetId ? (
          <IframeWidget
            key={SRC_TYPE_WIDGET}
            widgetId={htmlData.widgetId}
            isViewer={isViewer}
            onHeightChange={setHeight}
            colorPalette={settings.getColorPalette?.()}
          />
        ) : html ? (
          <IframeHtml
            iframeSandboxDomain={iframeSandboxDomain || 'https://www.filesusr.com'}
            key={SRC_TYPE_HTML}
            html={html}
            onHeightChange={setHeight}
            isViewer={isViewer}
          />
        ) : htmlData.url && containsUrl(htmlData.url) ? (
          <IframeUrl
            key={SRC_TYPE_URL}
            // @ts-ignore
            tabIndex={0}
            src={normalizeUrl(htmlData.url)}
            isViewer={isViewer}
          />
        ) : (
          <div className={htmlStyles.htmlComponent_placeholder} />
        )}
      </div>
    );
  }
);
